package com.sertumrosarum.domain.formation

import java.text.Normalizer
import java.util.Locale

/** Original editorial catechesis. References identify support, not verbatim quotations or ecclesial approval. */
data class FormationLesson(
    val id: String, val pillar: String, val title: String, val objective: String,
    val teaching: String, val scripture: String, val catechism: String,
    val question: String, val choices: List<String>, val correct: Int, val explanation: String,
    val practice: String, val prayer: String, val keywords: String,
    val revision: Int = 1, val editorialDate: String = "13/11/2026", val theologicalReviewer: String? = null,
)
data class FaithQuestion(val id: String, val question: String, val answer: String, val references: String, val keywords: String)
data class PracticeJourney(val id: String, val title: String, val introduction: String, val steps: List<String>, val references: String)

object FormationCatalog {
    val pillars = listOf("A fé que professamos", "A fé que celebramos", "A fé que vivemos", "A fé que rezamos")
    private fun lesson(id: String, pillar: Int, title: String, objective: String, teaching: String, scripture: String, catechism: String,
        question: String, right: String, other: String, explanation: String, practice: String, prayer: String, keywords: String) =
        FormationLesson(id, pillars[pillar], title, objective, teaching, scripture, catechism, question, listOf(right, other), 0, explanation, practice, prayer, keywords)
    val lessons = listOf(
        lesson("god-loves", 0, "Deus vem ao nosso encontro", "Reconhecer a fé como resposta ao amor de Deus.",
            "A fé cristã começa com Deus que se dá a conhecer. Ele nos cria por amor e nos chama à comunhão com Ele. Na história de Israel, prepara a vinda de Jesus; no Filho, revela plenamente Seu rosto.\n\nCrer é confiar em Deus e acolher o que Ele revela, com inteligência e liberdade. Dúvidas sinceras podem ser apresentadas na oração e no diálogo com a Igreja. Você não precisa compreender tudo para dar um primeiro passo de confiança.",
            "1 João 4, 9–10; Hebreus 1, 1–2", "CIC 27–30; 50–73; 142–165", "Como começa a vida de fé?", "Acolhendo a iniciativa amorosa de Deus.", "Conquistando o amor de Deus por desempenho.",
            "Deus nos ama primeiro. Nossa resposta livre cresce ao escutar Sua Palavra, rezar e participar da vida da Igreja.", "Reserve dois minutos de silêncio e apresente a Deus uma pergunta sincera.", "Pai, ensina-me a reconhecer o Teu amor e a responder com confiança.", "iniciante começar duvida amor revelação credo"),
        lesson("trinity", 0, "Um só Deus, Pai, Filho e Espírito Santo", "Distinguir as três Pessoas da unidade de Deus.",
            "Os cristãos professam um só Deus em três Pessoas: Pai, Filho e Espírito Santo. Não são três deuses nem três disfarces de uma única Pessoa. Cada Pessoa é verdadeiramente Deus; a natureza divina é uma só.\n\nJesus nos revela o Pai e promete o Espírito Santo. A Trindade é um mistério que recebemos da revelação, não um problema que uma comparação humana consiga esgotar. Ao fazer o sinal da cruz, entramos conscientemente nessa relação de amor.",
            "Mateus 28, 19; João 14, 16–17", "CIC 232–267", "O que professamos na Trindade?", "Um só Deus em três Pessoas distintas.", "Três deuses que cooperam entre si.", "A distinção das Pessoas não divide a única natureza divina.", "Faça o sinal da cruz devagar, prestando atenção aos nomes do Pai, do Filho e do Espírito Santo.", "Glória a Ti, Pai, Filho e Espírito Santo.", "trindade sinal cruz consubstancial espírito"),
        lesson("jesus", 0, "Jesus Cristo, verdadeiro Deus e homem", "Compreender a Encarnação como centro da fé.",
            "O Filho eterno de Deus assumiu nossa natureza humana sem deixar de ser Deus. Jesus tem um corpo, inteligência e vontade humanos verdadeiros; Sua humanidade não é uma aparência. Em uma única Pessoa divina, Ele é verdadeiro Deus e verdadeiro homem.\n\nSua vida, morte e ressurreição nos reconciliam com Deus. Contemplar os mistérios do rosário é aproximar-se dessa vida concreta. Maria nos conduz ao Filho que ela acolheu na fé.",
            "João 1, 14; Filipenses 2, 6–11", "CIC 422–483; 599–655", "Quem é Jesus?", "O Filho de Deus feito verdadeiramente homem.", "Um homem admirável que apenas parece divino.", "A Encarnação une a natureza humana e a natureza divina na única Pessoa do Filho.", "Leia João 1, 14 e reconheça uma situação humana que deseja apresentar a Jesus.", "Jesus, aproxima de Ti a minha vida inteira.", "jesus encarnação salvação ressurreição natal"),
        lesson("church-mary", 0, "A Igreja, os santos e Maria", "Distinguir adoração e intercessão.",
            "Pelo Batismo, Cristo nos reúne em Seu Corpo, a Igreja. A comunhão dos santos une os fiéis na partilha dos dons de Deus e na oração uns pelos outros. Pedir a intercessão de um santo é pedir que reze conosco, sempre por Cristo.\n\nA adoração pertence somente a Deus. A veneração dos santos e a honra especial dada a Maria reconhecem o que a graça realizou neles. Maria é criatura e discípula: sua maternidade espiritual depende inteiramente da única mediação de Jesus.",
            "1 Coríntios 12, 12–27; Lucas 1, 38–48; 1 Timóteo 2, 5", "CIC 946–975; 2096–2097", "O que significa pedir a intercessão de Maria?", "Pedir que ela reze conosco a Deus, por Cristo.", "Adorá-la como uma deusa independente de Jesus.", "Toda intercessão cristã participa da única mediação de Cristo; a adoração é devida somente a Deus.", "Reze uma Ave-Maria por alguém e ofereça também uma ajuda concreta.", "Maria, ensina-me a escutar e seguir Jesus.", "maria santos adoração veneração idolatria intercessão"),
        lesson("sacraments", 1, "Os sacramentos: Cristo age na Igreja", "Conhecer os sete sacramentos como dons de Cristo.",
            "Os sacramentos são sinais eficazes da graça, instituídos por Cristo e confiados à Igreja. Neles, o Senhor age por meio de sinais visíveis. Não são magia: a graça é dom gratuito e chama nossa resposta de fé.\n\nSão sete: Batismo, Confirmação, Eucaristia, Penitência, Unção dos Enfermos, Ordem e Matrimônio. Os três primeiros iniciam a vida cristã; Penitência e Unção são sacramentos de cura; Ordem e Matrimônio servem à comunhão e à missão.",
            "Mateus 28, 19; João 20, 22–23", "CIC 1113–1134; 1210–1212", "O que é um sacramento?", "Um sinal eficaz da graça, no qual Cristo age.", "Um gesto mágico que dispensa a fé e a conversão.", "É Cristo quem age no sacramento; a disposição do fiel importa para acolher seus frutos.", "Recorde a data do seu Batismo ou pergunte à sua família sobre esse dia.", "Senhor, abre meu coração à graça dos Teus sacramentos.", "sete sacramentos batismo confirmação crisma matrimônio ordem unção"),
        lesson("mass", 1, "Participar da Missa com compreensão", "Reconhecer a unidade da Palavra e da Eucaristia.",
            "Na Missa, a Igreja escuta a Palavra de Deus e celebra a Eucaristia. O rito inicial nos reúne; as leituras, a homilia, a profissão de fé e as preces dispõem o coração. Na liturgia eucarística, apresentamos os dons, damos graças na oração eucarística e recebemos a Comunhão quando devidamente preparados.\n\nA Missa torna presente sacramentalmente o único sacrifício de Cristo; não é uma nova crucifixão. Ao final, somos enviados a viver o que celebramos no serviço aos irmãos.",
            "Lucas 24, 13–35; 1 Coríntios 11, 23–26", "CIC 1345–1355; 1362–1372", "O que celebramos na Missa?", "O único sacrifício de Cristo tornado presente sacramentalmente.", "Uma nova morte de Jesus a cada celebração.", "O sacrifício de Cristo é único; sua presença sacramental nos une à entrega do Senhor.", "Antes da próxima Missa, leia o Evangelho do dia e leve uma intenção.", "Jesus, faz da minha vida uma oferta unida à Tua.", "missa liturgia palavra eucaristia sacrifício altar"),
        lesson("eucharist", 1, "A presença real de Jesus", "Compreender a Eucaristia e preparar a Comunhão.",
            "Na consagração, o pão e o vinho se tornam verdadeiramente o Corpo e o Sangue de Cristo; as aparências do pão e do vinho permanecem. A Igreja chama essa mudança de transubstanciação. A presença eucarística não depende de nossa emoção ou imaginação.\n\nA Comunhão une a Cristo e à Igreja. Quem tem consciência de pecado grave deve receber a Reconciliação antes de comungar, salvo as condições excepcionais indicadas pela Igreja. Observe o jejum eucarístico conforme a disciplina da Igreja, com as exceções previstas para enfermos e seus cuidadores. Na dúvida, converse com o sacerdote.",
            "João 6, 51; 1 Coríntios 11, 27–29", "CIC 1373–1381; 1385–1389", "O que permanece depois da consagração?", "As aparências do pão e do vinho; Cristo está realmente presente.", "Somente pão e vinho que lembram um amigo ausente.", "A presença de Cristo é real e substancial. A linguagem de sinal não elimina essa realidade.", "Permaneça alguns minutos em ação de graças depois da Missa, mesmo se não tiver comungado.", "Jesus presente na Eucaristia, aumenta minha fé e minha caridade.", "comunhão presença real transubstanciação hóstia jejum"),
        lesson("reconciliation", 1, "Voltar ao Pai na Reconciliação", "Preparar uma confissão com confiança.",
            "O pecado fere nossa relação com Deus e com os outros. No sacramento da Penitência, Cristo oferece o perdão por meio do ministério do sacerdote. Preparar-se inclui examinar a consciência, arrepender-se e querer mudar, confessar sinceramente os pecados e cumprir a penitência recebida.\n\nOs pecados mortais de que temos consciência devem ser confessados em espécie e número, tanto quanto possível após exame diligente. Não é necessário inventar certezas ou repetir indefinidamente confissões já feitas. Se você sofre com escrúpulos, procure acompanhamento estável de um confessor.",
            "Lucas 15, 11–32; João 20, 22–23", "CIC 1422–1498", "Qual atitude prepara a confissão?", "Arrependimento sincero e disposição de recomeçar.", "Esconder deliberadamente o que precisa de reconciliação.", "A misericórdia convida à verdade e à conversão. O sacerdote pode ajudar quem não sabe por onde começar.", "Reserve um tempo sereno para examinar a consciência e procure os horários de confissão da sua paróquia.", "Pai de misericórdia, dá-me coragem para voltar a Ti.", "confissão perdão penitência pecado escrúpulos reconciliação"),
        lesson("dignity", 2, "A dignidade de cada pessoa", "Relacionar a imagem de Deus ao amor ao próximo.",
            "Cada pessoa é criada à imagem de Deus e possui dignidade que não depende de utilidade, saúde, riqueza ou reconhecimento. A vida em Cristo começa pela graça e cresce na liberdade de amar. Os mandamentos protegem a relação com Deus e o bem do próximo.\n\nJesus resume a Lei no amor a Deus e ao próximo. Esse amor tem forma concreta: verdade, justiça, proteção dos vulneráveis e responsabilidade nas escolhas. A consciência precisa ser formada à luz da Palavra e do ensinamento da Igreja.",
            "Gênesis 1, 27; Mateus 22, 34–40", "CIC 1700–1715; 1776–1802; 2052–2082", "De que depende a dignidade humana?", "De sermos criados à imagem de Deus.", "De produtividade, sucesso e reconhecimento.", "A dignidade é própria da pessoa e fundamenta o respeito também a quem parece não ter nada a oferecer.", "Dê atenção respeitosa a alguém que costuma ser ignorado.", "Senhor, ensina-me a reconhecer Tua imagem em cada pessoa.", "dignidade moral consciência mandamentos amor vida"),
        lesson("grace-freedom", 2, "Graça, liberdade e conversão", "Distinguir dom de Deus e responsabilidade humana.",
            "A graça é o favor gratuito de Deus que nos torna participantes de Sua vida. Não compramos a salvação nem produzimos sozinhos a santidade. Ao mesmo tempo, Deus respeita nossa liberdade e nos chama a cooperar com Sua graça.\n\nPecar é afastar-se do amor de Deus. Para um pecado ser mortal, são necessárias juntas matéria grave, plena consciência e consentimento deliberado. Nem todo erro ou pensamento involuntário é pecado mortal. A avaliação pessoal delicada merece diálogo com um confessor, sem transformar a consciência em medo constante.",
            "Efésios 2, 8–10; João 15, 5", "CIC 1846–1864; 1996–2005", "Como respondemos à graça?", "Cooperando livremente com o dom de Deus.", "Comprando o amor de Deus por boas notas espirituais.", "Até nossa resposta é sustentada pela graça; isso não elimina a liberdade e a responsabilidade.", "Reconheça uma escolha que pode mudar hoje e peça ajuda a Deus para dar esse passo.", "Senhor, sustenta minha liberdade no caminho do bem.", "graça pecado mortal venial salvação liberdade mérito"),
        lesson("mercy", 2, "A fé se torna misericórdia", "Praticar o amor em obras corporais e espirituais.",
            "A fé viva atua pela caridade. Alimentar quem tem fome, visitar enfermos, acolher quem precisa e cuidar dos que sofrem são expressões do encontro com Cristo. Também ensinamos com paciência, consolamos, perdoamos e rezamos pelos vivos e pelos mortos.\n\nA caridade inclui atenção às causas da injustiça e respeito à dignidade de quem recebe ajuda. Não precisamos resolver tudo num dia: um gesto possível, responsável e discreto pode ser nosso primeiro passo.",
            "Mateus 25, 31–46; Tiago 2, 14–18", "CIC 1822–1829; 2443–2449", "Como cresce uma fé viva?", "Em amor que também se expressa em ações concretas.", "Em palavras religiosas sem atenção ao próximo.", "As obras de misericórdia tornam visível o amor recebido de Deus.", "Escolha uma obra de misericórdia possível nesta semana e combine um primeiro passo.", "Jesus, abre meus olhos às necessidades que posso acolher.", "misericórdia caridade pobres justiça obras serviço"),
        lesson("forgiveness", 2, "Perdoar com verdade", "Distinguir perdão, reconciliação e proteção.",
            "Jesus nos chama a perdoar como fomos perdoados. O perdão é uma decisão de renunciar à vingança e entregar a ferida à misericórdia de Deus. A dor pode demorar a passar; sentir tristeza não significa que todo esforço de perdão foi falso.\n\nPerdoar não exige negar o mal, abandonar a justiça ou voltar a uma situação de abuso. Reconciliação e reconstrução da confiança pedem verdade, mudança e condições seguras. Procure ajuda humana e pastoral quando a ferida for grande.",
            "Mateus 18, 21–35; Romanos 12, 17–21", "CIC 2840–2845; 2264–2265", "Perdoar exige aceitar novos abusos?", "Não. Perdão e proteção podem caminhar juntos.", "Sim. Buscar proteção sempre demonstra falta de fé.", "A misericórdia não elimina a dignidade, a justiça e o cuidado com a vida.", "Apresente uma ferida a Deus e escolha um passo seguro, sem se obrigar a um contato que o coloque em risco.", "Pai, acolhe minha dor e guia-me na verdade e na paz.", "perdão abuso sofrimento reconciliação vingança"),
        lesson("prayer", 3, "Rezar é encontrar-se com Deus", "Começar uma oração simples e sincera.",
            "A oração é relação viva com Deus: escuta e resposta, louvor e pedido, gratidão e entrega. Ela pode usar palavras conhecidas, uma leitura bíblica, o silêncio ou um pedido muito simples. O Pai-Nosso, ensinado por Jesus, é a escola fundamental da oração cristã.\n\nDistração e aridez são experiências frequentes. Voltar com mansidão à presença de Deus é parte do caminho. A qualidade da oração não se mede por sensações intensas ou por uma sequência perfeita de dias.",
            "Mateus 6, 5–13; Romanos 8, 26", "CIC 2558–2565; 2759–2865", "O que fazer quando me distraio?", "Retomar a oração com paciência e confiança.", "Concluir que Deus rejeitou minha oração.", "A fidelidade humilde pode crescer mesmo quando não sentimos consolo.", "Reze um Pai-Nosso devagar e permaneça um minuto em silêncio.", "Pai, aqui estou. Ensina-me a rezar.", "oração iniciar distração aridez ansiedade pai nosso"),
        lesson("rosary", 3, "O rosário: contemplar Cristo com Maria", "Entender a repetição como apoio à contemplação.",
            "No rosário, meditamos os acontecimentos da vida de Cristo com Maria. A repetição das Ave-Marias oferece um ritmo para a atenção do coração. Não é a quantidade de palavras que força uma resposta de Deus.\n\nUma dezena reúne o anúncio do mistério, o Pai-Nosso, dez Ave-Marias, o Glória e, conforme o costume, a oração de Fátima. Comece pelo que consegue rezar com atenção; uma dezena pode ser uma boa entrada. As meditações e os frutos ajudam a ligar o Evangelho à vida.",
            "Lucas 2, 19; Mateus 6, 7–8", "CIC 971; 2678; 2708", "Qual é o centro da contemplação do rosário?", "Jesus Cristo, contemplado com Maria.", "Uma contagem que obriga Deus a conceder pedidos.", "A repetição serve à contemplação e à confiança, sem fórmulas de controle sobre Deus.", "Contemple a Anunciação e reze uma dezena, deixando uma frase do Evangelho acompanhar as contas.", "Maria, ajuda-me a guardar a Palavra no coração.", "terço rosário repetição ave maria mistérios iniciante"),
        lesson("year", 3, "Rezar com o ano da Igreja", "Reconhecer os tempos litúrgicos.",
            "Ao longo do ano litúrgico, a Igreja celebra o mistério de Cristo: Advento prepara o Natal; a Quaresma nos conduz à Páscoa; o Tempo Pascal celebra a Ressurreição até Pentecostes. O Tempo Comum aprofunda o seguimento de Jesus na vida cotidiana.\n\nOs domingos e as festas não são apenas lembranças distantes: a liturgia nos faz participar da obra de Cristo. Os calendários e as transferências de celebrações variam conforme o país e a diocese; consulte a sua comunidade para as celebrações locais.",
            "Lucas 4, 16–21; Atos 2, 1–4", "CIC 1163–1173", "O que organiza o ano litúrgico?", "A celebração do mistério de Cristo ao longo do tempo.", "Uma previsão pessoal de graças e acontecimentos.", "A liturgia santifica o tempo ao nos unir à vida, morte e ressurreição do Senhor.", "Veja no calendário da sua paróquia a próxima celebração e prepare uma intenção.", "Senhor do tempo, ajuda-me a viver cada dia em Tua presença.", "advento natal quaresma páscoa pentecostes calendário litúrgico"),
        lesson("daily", 3, "Um ritmo possível para cada dia", "Criar uma prática de oração livre de cobrança.",
            "Uma rotina simples pode abrir espaço para Deus: oferecer o dia ao acordar, lembrar-se de Sua presença numa pausa e rever a jornada à noite. A regularidade serve ao encontro; não transforma a oração em competição.\n\nNo exame do dia, agradeça um dom, reconheça uma atitude que precisa de conversão, peça perdão e escolha um passo possível para amanhã. Se perdeu um dia, retorne com liberdade. A oração pessoal cresce junto da participação na comunidade e dos sacramentos.",
            "1 Tessalonicenses 5, 16–18; Lucas 11, 1", "CIC 2697–2699; 2725–2745", "Como retomar depois de um período sem rezar?", "Recomeçar com um passo pequeno e confiança.", "Esperar até conseguir cumprir uma rotina perfeita.", "A constância se constrói pelo retorno amoroso, sem transformar dificuldades em culpa automática.", "Escolha um momento realista de dois minutos e registre no Jardim uma intenção para esse encontro.", "Senhor, recebe este pequeno tempo e ensina-me a voltar.", "rotina noite manhã exame consciência perseverança"),
    )
    val questions = listOf(
        FaithQuestion("mary", "Por que os católicos pedem a intercessão de Maria?", "Assim como pedimos a um irmão que reze por nós, pedimos a Maria que interceda. Ela está unida a Cristo e toda sua ajuda depende Dele. A Igreja distingue essa veneração da adoração, devida somente a Deus.", "CIC 956; 969–971; 1 Timóteo 2, 5", "maria adorar idolatria santos rezam mortos imagem"),
        FaithQuestion("repeat", "Jesus não proibiu repetir orações?", "Jesus critica palavras vazias e a tentativa de ser ouvido pela quantidade de palavras. A repetição atenta pode apoiar a contemplação, como nos salmos e no rosário. O coração busca Deus em vez de controlar uma resposta.", "CIC 2700–2708; Mateus 6, 7–8", "terço repetição repetidas ave maria vãs palavras"),
        FaithQuestion("suffering", "Por que Deus permite o sofrimento?", "A fé não oferece uma explicação simples para cada dor. Deus não é autor do mal moral; respeita a liberdade e pode tirar um bem do mal sem tornar bom o próprio mal. Na cruz e na ressurreição, Cristo entra em nosso sofrimento e abre uma esperança. A oração acompanha o cuidado concreto e a busca de ajuda.", "CIC 309–314; 618; Romanos 8, 28–39", "mal doença luto morte injustiça dor permite sofrer"),
        FaithQuestion("confess", "Por que confessar a um sacerdote?", "Jesus confiou à Igreja o ministério da reconciliação. O sacerdote age como ministro de Cristo, e a absolvição sacramental oferece a certeza do perdão a quem se arrepende e confessa sinceramente. Você pode dizer ao confessor que não sabe como começar.", "CIC 1441–1449; João 20, 22–23", "confissão padre vergonha pecado penitência perdão"),
        FaithQuestion("mortal", "Todo pecado é mortal?", "Não. Para o pecado mortal, matéria grave, plena consciência e consentimento deliberado devem estar presentes juntos. O pecado venial também fere a caridade, mas não rompe a aliança da mesma forma. Dúvidas pessoais devem ser tratadas com serenidade junto de um confessor.", "CIC 1854–1864", "grave venial culpa pensamento escrúpulos"),
        FaithQuestion("distraction", "Minha oração vale quando estou distraído?", "A distração revela o que ocupa nossa atenção. Podemos voltar mansamente a Deus, sem contar cada distração como uma falha moral. A oração é um encontro que cresce com perseverança, também na aridez.", "CIC 2729–2731", "distraído concentração foco aridez seco sentir nada"),
        FaithQuestion("eucharist", "A Eucaristia é apenas um símbolo?", "A Eucaristia é sacramento e presença verdadeira de Cristo. Na consagração, a substância do pão e do vinho se converte no Corpo e no Sangue do Senhor; permanecem as aparências sensíveis. A presença não depende de nossa emoção.", "CIC 1373–1381; 1 Coríntios 11, 23–26", "hóstia presença real transubstanciação pão vinho comunhão"),
        FaithQuestion("communion", "Como me preparar para comungar?", "Acolha a fé da Igreja, participe com atenção e observe o jejum eucarístico segundo a disciplina da Igreja e suas exceções. Quem tem consciência de pecado grave deve procurar a Reconciliação antes da Comunhão, salvo as condições excepcionais previstas. Um sacerdote pode orientar sua situação concreta.", "CIC 1385–1389", "comungar preparação missa jejum pecado"),
        FaithQuestion("forgive", "Perdoar significa voltar a uma situação que me machuca?", "Não. Perdoar é renunciar à vingança e buscar a misericórdia; não exige negar o mal ou abrir mão da proteção e da justiça. A reconstrução da confiança depende de verdade e mudança. Busque apoio humano e pastoral em situações de violência.", "CIC 2840–2845; 2264–2265", "abuso violência reconciliação perdão machucado"),
        FaithQuestion("grace", "O que significa graça?", "Graça é o dom gratuito pelo qual Deus nos chama a participar de Sua vida e nos ajuda a responder ao Seu amor. Não é um prêmio reservado a quem nunca falha. A graça sustenta nossa liberdade e nossa conversão.", "CIC 1996–2005; Efésios 2, 8–10", "salvação merecer dom favor gratuita cheia de graça"),
        FaithQuestion("baptism", "O que acontece no Batismo?", "O Batismo nos liberta do pecado, nos faz filhos de Deus em Cristo e nos incorpora à Igreja. É o nascimento para a vida nova no Espírito e a porta dos outros sacramentos. Essa graça pede desenvolvimento na fé e na vida cristã.", "CIC 1213; 1262–1274; Romanos 6, 3–4", "batizar criança filhos igreja água"),
        FaithQuestion("start", "Não sei rezar. Por onde começo?", "Apresente-se a Deus com sinceridade. Leia uma pequena passagem do Evangelho, reze o Pai-Nosso devagar ou diga uma frase simples de confiança. Um pequeno tempo possível, retomado com liberdade, ajuda a aprender.", "CIC 2558–2565; 2759–2766; Lucas 11, 1", "iniciante aprender começar oração"),
    )
    val journeys = listOf(
        PracticeJourney("mass", "Antes, durante e depois da Missa", "Um caminho de participação consciente, em comunhão com a sua paróquia.", listOf("Antes: leia o Evangelho do dia no material da sua comunidade e apresente uma intenção.", "Na Palavra: escute uma frase e deixe que questione sua vida. Participe das respostas e do silêncio.", "Na Eucaristia: una sua vida à oferta de Cristo. Para comungar, observe a preparação da Igreja; na dúvida, peça orientação ao sacerdote.", "Depois: permaneça em ação de graças e escolha um gesto de serviço para a semana."), "CIC 1345–1355; 1385–1389"),
        PracticeJourney("confession", "Preparar uma confissão", "Um retorno confiante à misericórdia, sem pressa ou interrogatórios automáticos.", listOf("Peça luz ao Espírito Santo. Agradeça a Deus por Seu amor antes de olhar suas faltas.", "Examine suas relações: tenho colocado Deus no centro? Tenho sido verdadeiro, justo e caridoso em casa, no trabalho e com quem precisa?", "Reconheça os pecados com sinceridade, arrependa-se e decida mudar. Anote apenas o necessário se isso ajudar.", "Procure o sacerdote. Confesse os pecados graves em espécie e número, tanto quanto recordar após exame diligente. Diga se precisa de ajuda.", "Acolha a absolvição e cumpra a penitência. Se houver escrúpulos, siga a orientação de um confessor estável."), "CIC 1450–1460; 1480–1484"),
        PracticeJourney("evening", "Rever o dia com Deus", "Cinco minutos para agradecer, reconhecer e recomeçar.", listOf("Faça silêncio e reconheça que Deus o olha com amor.", "Recorde um dom do dia e agradeça por ele.", "Reveja uma escolha: onde houve amor? Onde faltou verdade ou caridade?", "Peça perdão e escolha um pequeno passo concreto para amanhã.", "Entregue o que não pode resolver hoje e registre uma reflexão no Jardim, se desejar."), "CIC 1779; 2698; 1 Tessalonicenses 5, 18"),
        PracticeJourney("mercy", "Uma semana de misericórdia", "Escolha um gesto possível. A dignidade de quem recebe ajuda vem primeiro.", listOf("Perceba uma necessidade concreta na família, na vizinhança ou na comunidade.", "Pergunte como ajudar, respeitando a vontade e a privacidade da pessoa.", "Ofereça alimento, companhia, escuta, tempo ou colaboração com uma obra da sua paróquia.", "Reze por quem encontrou e agradeça pelo bem que também recebeu.", "Reveja a experiência com liberdade. Você pode continuar o gesto sem transformar o cuidado em cobrança."), "CIC 2443–2449; Mateus 25, 31–46"),
    )
    fun lesson(id: String?) = lessons.find { it.id == id }
    fun fold(value: String) = Normalizer.normalize(value, Normalizer.Form.NFD).replace(Regex("\\p{M}+"), "").lowercase(Locale.ROOT).replace(Regex("[^\\p{L}\\p{N}]+"), " ").trim()
    private val stop = setOf("por", "que", "os", "as", "a", "o", "de", "da", "do", "um", "uma", "e", "em", "na", "no", "para", "como", "me", "eu", "se", "ao", "com", "nao", "dos", "das", "catolicos")
    fun matches(query: String, text: String): Int {
        val words = fold(query.take(300)).split(' ').filter { it.isNotBlank() && it !in stop }
        if (query.isBlank()) return 1
        if (words.isEmpty()) return 0
        val haystack = fold(text)
        return words.count { word -> word in haystack }.takeIf { it * 2 >= words.size } ?: 0
    }
    fun searchQuestions(query: String) = questions.map { it to matches(query, "${it.question} ${it.answer} ${it.keywords}") }.filter { it.second > 0 }.sortedByDescending { it.second }.map { it.first }
}
